#pragma once

static const char kRecognitionHtml[] = R"HTML(
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>NEWO2 Face Recognition Test</title>
<style>
body{margin:0;background:#0a0a0a;color:#eee;font-family:Arial,sans-serif}.wrap{max-width:920px;margin:auto;padding:14px}.title{font-size:21px;font-weight:700}.sub{color:#999;font-size:13px;margin:5px 0 12px}.stage{position:relative;width:100%;background:#111;aspect-ratio:4/3;overflow:hidden;border:1px solid #333}.stage img{width:100%;height:100%;object-fit:contain;display:block}.stage img.mirrored{transform:scaleX(-1)}.stage img.flipped{transform:scaleY(-1)}.stage img.mirrored.flipped{transform:scale(-1,-1)}.box{position:absolute;border:2px solid #00e676;box-sizing:border-box;pointer-events:none}.box span{position:absolute;left:-2px;top:-22px;background:#00e676;color:#000;padding:2px 5px;font-size:12px;font-weight:700;white-space:nowrap}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin-top:10px}.card{background:#151515;border:1px solid #292929;padding:10px;border-radius:8px}.big{font-size:28px;font-weight:700}.ok{color:#00e676}.warn{color:#ffca28}.bad{color:#ff5252}.muted{color:#888}.row{display:flex;justify-content:space-between;gap:12px;padding:3px 0;font-size:13px}.controls{display:flex;flex-wrap:wrap;gap:7px;margin-top:10px}button{background:#222;color:#eee;border:1px solid #444;border-radius:7px;padding:10px 12px;font-weight:700}button:active{background:#333}.primary{border-color:#00e676}.danger{border-color:#ff5252}.active{background:#eaeaea;color:#000}.slider{display:flex;gap:8px;align-items:center;margin-top:10px;font-size:13px}.slider input{flex:1}.note{font-size:12px;color:#aaa;margin-top:9px;line-height:1.4}.status{font-size:13px;margin-top:9px;padding:8px 10px;border:1px solid #333;border-radius:7px;background:#111;color:#aaa}@media(max-width:640px){.grid{grid-template-columns:1fr}.wrap{padding:9px}}
</style></head><body><div class="wrap">
<div class="title">NEWO2 · face recognition product gate</div><div class="sub">OV3660 VGA native JPEG · ESPDet-224 @ 0.30 · MFN_S8_V1</div>
<div id="stage" class="stage"><img id="stream" src="http://192.168.4.1:81/stream"></div>
<div class="grid">
 <div class="card"><div class="muted">IDENTITY</div><div id="identity" class="big">NOT ENROLLED</div><div class="row"><span>Similarity max</span><b id="simmax">—</b></div><div class="row"><span>Similarity avg</span><b id="simavg">—</b></div><div class="row"><span>Recognition</span><b id="recms">—</b></div><div class="row"><span>Enrollment samples</span><b id="enrollcount">0 / 5</b></div></div>
 <div class="card"><div class="muted">END-TO-END TEST</div><div id="accuracy" class="big">—</div><div class="row"><span>Expected</span><b id="expected">OFF</b></div><div class="row"><span>Test frames</span><b id="testframes">0</b></div><div class="row"><span>Faces available</span><b id="faceframes">0</b></div><div class="row"><span>Recognition attempts</span><b id="recattempts">0</b></div><div class="row"><span>Correct classifications</span><b id="correct">0</b></div></div>
 <div class="card"><div class="muted">VISION</div><div class="row"><span>Faces now</span><b id="faces">0</b></div><div class="row"><span>Largest face</span><b id="facesize">—</b></div><div class="row"><span>JPEG decode</span><b id="decode">—</b></div><div class="row"><span>ESPDet detect</span><b id="detect">—</b></div><div class="row"><span>Total AI</span><b id="aitotal">—</b></div></div>
 <div class="card"><div class="muted">MEMORY / CAMERA</div><div class="row"><span>JPEG frame</span><b id="jpegbytes">—</b></div><div class="row"><span>Free PSRAM</span><b id="psram">—</b></div><div class="row"><span>Largest PSRAM</span><b id="largest">—</b></div><div class="row"><span>Internal RAM</span><b id="internal">—</b></div><div class="row"><span>JPEG rejects</span><b id="rejects">0</b></div><div class="row"><span>Pool drops</span><b id="drops">0</b></div></div>
</div>
<div class="controls"><button id="enrollbtn" class="primary" onclick="enrollNow()">Enroll current face</button><button class="danger" onclick="clearEnrollment()">Clear enrollment</button><button id="mebtn" onclick="setExpected('me')">Test: ME</button><button id="otherbtn" onclick="setExpected('other')">Test: OTHER</button><button onclick="setExpected('off')">Stop scoring</button><button onclick="cmd('/reset_test')">Reset counters</button><button id="mirrorbtn" onclick="toggleMirror()">Mirror preview: OFF</button><button id="flipbtn" onclick="toggleFlip()">Flip preview: OFF</button></div>
<div id="enrollstatus" class="status">Enrollment: idle. Keep exactly one face in the green box before pressing Enroll.</div>
<div class="slider"><span>Recognition threshold</span><input id="rthr" type="range" min="0.35" max="0.80" step="0.01" value="0.50"><b id="rthrval">0.50</b></div>
<div class="note">Enrollment is RAM-only for this product-gate firmware. Enroll 3–5 samples of one person from slightly different angles. Then run ME and OTHER tests from the real room positions you care about. A face detection miss and an identity mismatch are reported separately. Mirror and Flip change only what you see in this browser; AI input and enrollment stay unchanged.</div>
</div>
<script>
const $=id=>document.getElementById(id);let lastBoxes=[];let mirrorPreview=localStorage.getItem('newo2MirrorPreview')==='1';let flipPreview=localStorage.getItem('newo2FlipPreview')==='1';let enrollRequestedAt=0;let enrollStartCount=0;let lastEnrollCount=0;
async function cmd(path){try{let r=await fetch(path,{cache:'no-store'});return r.ok}catch(e){return false}}
async function enrollNow(){let b=$('enrollbtn');b.classList.add('active');enrollRequestedAt=Date.now();enrollStartCount=lastEnrollCount;$('enrollstatus').textContent='Enrollment request sent — hold exactly one face steady inside the green box.';let ok=await cmd('/enroll');if(!ok){$('enrollstatus').textContent='Enrollment request failed to reach the ESP.';enrollRequestedAt=0}setTimeout(()=>b.classList.remove('active'),500)}
async function clearEnrollment(){await cmd('/clear');enrollRequestedAt=0;enrollStartCount=0;lastEnrollCount=0;$('enrollstatus').textContent='Enrollment cleared.'}
async function setExpected(v){await cmd('/expected?value='+v);$('mebtn').classList.toggle('active',v==='me');$('otherbtn').classList.toggle('active',v==='other');}
function applyOrientation(){let stream=$('stream'),mbtn=$('mirrorbtn'),fbtn=$('flipbtn');stream.classList.toggle('mirrored',mirrorPreview);stream.classList.toggle('flipped',flipPreview);mbtn.textContent='Mirror preview: '+(mirrorPreview?'ON':'OFF');fbtn.textContent='Flip preview: '+(flipPreview?'ON':'OFF');mbtn.classList.toggle('active',mirrorPreview);fbtn.classList.toggle('active',flipPreview);localStorage.setItem('newo2MirrorPreview',mirrorPreview?'1':'0');localStorage.setItem('newo2FlipPreview',flipPreview?'1':'0');draw(lastBoxes)}
function toggleMirror(){mirrorPreview=!mirrorPreview;applyOrientation()}
function toggleFlip(){flipPreview=!flipPreview;applyOrientation()}
$('rthr').oninput=async e=>{let v=Number(e.target.value).toFixed(2);$('rthrval').textContent=v;await cmd('/rec_threshold?value='+v)};
function mb(n){return (n/1048576).toFixed(2)+' MB'}
function kb(n){return Math.round(n/1024)+' KB'}
function draw(boxes){lastBoxes=boxes||[];document.querySelectorAll('.box').forEach(x=>x.remove());let stage=$('stage'),r=stage.getBoundingClientRect();for(let b of lastBoxes){let d=document.createElement('div');d.className='box';let x=mirrorPreview?(640-b.x2):b.x1;let y=flipPreview?(480-b.y2):b.y1;d.style.left=(x/640*r.width)+'px';d.style.top=(y/480*r.height)+'px';d.style.width=((b.x2-b.x1)/640*r.width)+'px';d.style.height=((b.y2-b.y1)/480*r.height)+'px';let s=document.createElement('span');s.textContent=Math.round(b.score*100)+'%';d.appendChild(s);stage.appendChild(d)}}
async function poll(){try{let m=await (await fetch('/metrics',{cache:'no-store'})).json();let id=m.identity||'NOT ENROLLED';$('identity').textContent=id;$('identity').className='big '+(id==='ME'?'ok':id==='UNKNOWN'?'warn':id==='NO FACE'?'muted':'');$('simmax').textContent=m.recognition_ms?Number(m.similarity_max).toFixed(3):'—';$('simavg').textContent=m.recognition_ms?Number(m.similarity_avg).toFixed(3):'—';$('recms').textContent=m.recognition_ms?m.recognition_ms+' ms':'—';$('enrollcount').textContent=m.enrollment_count+' / 5';lastEnrollCount=m.enrollment_count;if(enrollRequestedAt&&m.enrollment_count>enrollStartCount){$('enrollstatus').textContent='Enrollment succeeded — sample '+m.enrollment_count+' / 5 stored in RAM.';enrollRequestedAt=0}else if(enrollRequestedAt&&Date.now()-enrollRequestedAt>5000){$('enrollstatus').textContent=m.faces===0?'Still waiting: ESPDet currently has NO FACE. Keep one face in the green box.':'Still waiting: face is detected but enrollment has not completed yet. Keep one face steady and check serial for landmark/MFN messages.'}$('expected').textContent=(m.expected||'off').toUpperCase();$('testframes').textContent=m.test_frames;$('faceframes').textContent=m.face_frames;$('recattempts').textContent=m.recognition_attempts;$('correct').textContent=m.correct_classifications;let a=m.test_frames?100*m.correct_classifications/m.test_frames:NaN;$('accuracy').textContent=Number.isFinite(a)?a.toFixed(1)+'%':'—';$('accuracy').className='big '+(a>=90?'ok':a>=70?'warn':Number.isFinite(a)?'bad':'');$('faces').textContent=m.faces;$('facesize').textContent=m.largest_face_w?m.largest_face_w+'×'+m.largest_face_h+' px':'—';$('decode').textContent=m.decode_ms+' ms';$('detect').textContent=m.detect_ms+' ms';$('aitotal').textContent=m.ai_total_ms+' ms';$('jpegbytes').textContent=m.jpeg_bytes?kb(m.jpeg_bytes):'—';$('psram').textContent=mb(m.psram_free);$('largest').textContent=mb(m.psram_largest);$('internal').textContent=Math.round(m.internal_free/1024)+' KB';$('rejects').textContent=m.jpeg_rejects;$('drops').textContent=m.pool_drops;$('rthr').value=m.recognition_threshold;$('rthrval').textContent=Number(m.recognition_threshold).toFixed(2);draw(m.boxes)}catch(e){}setTimeout(poll,500)}
applyOrientation();poll();
window.addEventListener('resize',()=>draw(lastBoxes));
</script></body></html>
)HTML";
